const filteredRows=(ctx,rows)=>rows.filter(r=>(!ctx.state.frequency||r.frequency===ctx.state.frequency)&&(!ctx.state.year||String(r.year||r.period_end||r.period).startsWith(ctx.state.year)));

export function seriesGroups(source,rows){const groups=new Map(),reset=source.annual_reset||['cumulative_ytd','currency_ytd','annual_cumulative','ytd'].includes(source.period_semantics);for(const p of rows){const category=typeof p.category==='object'?Object.values(p.category).join(' · '):p.category||'',year=String(p.year||p.period_end||p.period).slice(0,4),key=[p.frequency,category,reset?year:''].join('|');if(!groups.has(key))groups.set(key,{name:[FREQ[p.frequency]||p.frequency,category,reset?year:''].filter(Boolean).join(' · '),frequency:p.frequency,points:[]});groups.get(key).points.push({x:Date.parse(p.period_end||p.period),y:value(p),label:p.original_period_label||p.period});}
 return [...groups.values()].map(g=>{const sorted=g.points.filter(p=>Number.isFinite(p.x)).sort((a,b)=>a.x-b.x),points=[];for(const p of sorted){const last=points.at(-1);if(last&&['monthly','quarterly'].includes(g.frequency)){const a=new Date(last.x),b=new Date(p.x),distance=(b.getUTCFullYear()-a.getUTCFullYear())*12+b.getUTCMonth()-a.getUTCMonth();if(distance>(g.frequency==='quarterly'?3:1))points.push({x:Date.UTC(a.getUTCFullYear(),a.getUTCMonth()+2,0),y:null,label:'Период не опубликован'});}points.push(p);}return {...g,points};}).filter(g=>g.points.some(p=>Number.isFinite(p.y)));
}
function seriesFigure(ctx,s,rows,name='observations'){const groups=seriesGroups(s,rows).map((g,i)=>({...g,name:sourceName(s)+' · '+g.name,color:C[i%C.length]}));return h('div',{},legend(groups),chart(ctx,lineChart(groups,{height:350,unit:sourceUnit(s),label:sourceName(s),monthlyTicks:true}),sid(s)+'-'+name,sourceName(s),sourceText(ctx,s),observationRows(s,rows)),para('Пропуски разрывают линию. Отдельные типы периода показаны разными рядами. Исходные нули и исключённые записи доступны в таблице.','healthtech-chart-detail'));}
