const UPDATE_STATES={retained_republication:'Сохранена проверенная републикация',updated:'Обновлено',unchanged:'Без изменений',failed:'Проверка не завершена',error:'Ошибка запроса',network_error:'Сетевая ошибка',not_checked:'Не проверялся в запуске',metadata_only:'Числовая публикация отсутствует',unavailable:'Данные не получены',no_numeric:'Числовые данные не получены',http_error:'Ошибка ответа источника',validation_failed:'Проверка данных не пройдена',methodology_contract_changed:'Изменилась методика',unit_mismatch:'Изменилась единица',deferred_after_source_outage:'Отложено после ошибок доступа',blocked:'Доступ ограничен'};
