export async function healthtechPage(ctx){const pages={overview,framework,logic,audit,targets,map:territories,regions:readiness,finance,network,texts,domains,causal,proposals,projections:scenario,population,structure,methods,lab,explorer,library,updates};try{return await(pages[ctx.state.page]||overview)(ctx);}catch(error){if(!(error instanceof DataLoadError))throw error;const root=start(ctx),retry=button('Повторить загрузку',async()=>{retry.disabled=true;try{const replacement=await healthtechPage(ctx);if(root.isConnected)root.replaceWith(replacement);}finally{retry.disabled=false;}},'button primary','reset');append(root,panel('Источник временно не загрузился',null,h('div',{class:'healthtech-load-error',role:'alert'},para(error.message),para('Выбранные фильтры сохранены. Повторная попытка заново загружает файл источника.'),retry)));return end(ctx,root);}}
